#include <array>
#include <cstddef>
#include <iostream>
#include <string>

const int* consultar(const std::array<int, 3>& datos, int indice) {
    if (indice < 0 || indice > 2) {
        return nullptr;
    }
    return &datos.at(static_cast<std::size_t>(indice));
}

int main() {
    std::array<int, 3> datos{2, 5, 8};
    const std::array<int, 3> constantes{3, 6, 9};
    const int* lectura = consultar(datos, 1);
    const int* const fija = lectura;
    datos[1] = 7;
    lectura = consultar(constantes, 2);
    std::cout << *lectura << ':' << *fija << ':' << datos[1];
    return 0;
}

