#include <array>
#include <cstddef>
#include <iostream>
#include <string>

const int* consultar(const std::array<int, 3>& datos, int indice) {
    if (indice < 0 || indice > 2) {
        return nullptr;
    }
    return &datos.at(static_cast<std::size_t>(indice));
}

int main() {
    std::array<int, 3> datos{2, 5, 8};
    const int limite = 9;
    const int* vista = nullptr;
    int* const destino = &datos[1];
    const int* const tope = &limite;
    const int copia = *destino;
    int cantidad = 0;
    if (!(std::cin >> cantidad) || cantidad < 1 || cantidad > 12) {
        return 1;
    }
    for (int orden = 0; orden < cantidad; ++orden) {
        int operacion = 0;
        int argumento = 0;
        if (!(std::cin >> operacion >> argumento)) {
            return 1;
        }
        std::string estado = "Pendiente";
        if ((operacion == 2 || operacion == 3) &&
            (argumento < 0 || argumento > *tope)) {
            estado = "Rechazo";
        } else {
            if (operacion == 1) {
                vista = consultar(datos, argumento);
                if (vista == nullptr) {
                    estado = "Indice invalido";
                } else {
                    estado = "Elegida";
                }
            } else if (operacion == 2) {
                *destino = argumento;
                estado = "Cambio";
            } else if (operacion == 3) {
                datos[0] = argumento;
                estado = "Cambio";
            } else if (operacion == 4) {
                vista = nullptr;
                estado = "Sin vista";
            } else {
                estado = "Operacion invalida";
            }
        }
        std::cout << estado << ";Vista:";
        if (vista == nullptr) {
            std::cout << 'X';
        } else {
            std::cout << *vista;
        }
        std::cout << ";Destino:" << *destino << ";Copia:" << copia
                  << ";Datos:" << datos[0] << ',' << datos[1] << ',' << datos[2] << '\n';
    }
    return 0;
}
